package co.aplomo.web;
import co.aplomo.servicio.Consultas.*;import co.aplomo.dao.ConsultaDao.*;import co.aplomo.dao.SugerenciaDao.Contexto;import co.aplomo.modelo.*;import co.aplomo.seguridad.Sesiones.Sesion;
import java.util.*;import java.time.*;import java.net.URLEncoder;import java.nio.charset.StandardCharsets;import static co.aplomo.web.Html.escapar;import static co.aplomo.web.PaginasEmpresas.enlace;
/** RF-024, RNF-002/007: tablas y filtros del mock, conservando los parámetros al ordenar. */
public final class PaginasConsultas {
    private PaginasConsultas(){}
    /** Genera la sección con su contador, filtros y enlaces de ordenación accesibles. */
    public static String lista(Sesion sesion,Pagina pagina,Contexto contexto){
        var s=pagina.seccion();var f=pagina.filtros();boolean admin=sesion.cuenta().rol()==Cuenta.Rol.ADMINISTRADOR;
        String etiqueta=s==SeccionConsulta.EMPRESAS?"Gestión · Empresas":s==SeccionConsulta.RESERVAS?"Reservas · Consulta":s==SeccionConsulta.PENDIENTES?"Seguimiento · Pendientes":"Consultas · "+s.titulo();
        StringBuilder h=new StringBuilder(Html.encabezado(etiqueta,s.titulo(),admin?accion(s,f,contexto):""));
        h.append("<details class=\"guia consultas-secciones\"><summary>Ver otras secciones</summary><div class=\"row\">");
        for(var otra:SeccionConsulta.values())h.append(enlace(otra.ruta(),otra.titulo(),false));h.append("</div></details>");
        if(contexto!=null)h.append(PaginasSugerencias.contexto(contexto));
        h.append(filtros(pagina,contexto!=null));
        String contador=pagina.filas().isEmpty()?"0 resultados":pagina.filas().size()==1?"1 "+s.singular():pagina.filas().size()+" "+(s==SeccionConsulta.PENDIENTES?"pendientes":s.titulo().toLowerCase(Locale.forLanguageTag("es")));
        h.append("<p class=\"muted consultas-contador\" role=\"status\">").append(contador).append("</p>");
        if(pagina.filas().isEmpty())h.append(Html.vacio("No hay registros con estos filtros. Cambia la búsqueda o limpia los filtros.",""));
        else{
            var columnas=s.columnas().stream().filter(x->!(contexto!=null&&x.clave().equals("numero"))).toList();
            h.append("<div class=\"tablewrap\"><table class=\"resp consultas-table ").append(s==SeccionConsulta.SUGERENCIAS?"sugerencias-table":"").append("\"><thead><tr>");
            for(var col:columnas){boolean actual=f.get("orden").equals(col.clave());Map<String,String> parametros=new LinkedHashMap<>(f);parametros.put("orden",col.clave());parametros.put("direccion",actual&&f.get("direccion").equals("asc")?"desc":"asc");h.append("<th scope=\"col\" aria-sort=\"").append(actual?(f.get("direccion").equals("asc")?"ascending":"descending"):"none").append("\"><a class=\"orden-columna\" href=\"").append(escapar(url(s.ruta(),parametros))).append("\" aria-label=\"Ordenar por ").append(escapar(col.titulo())).append("\">").append(escapar(col.titulo())).append(actual?(f.get("direccion").equals("asc")?" ↑":" ↓"):"").append("</a></th>");}
            h.append("<th scope=\"col\">Detalle</th></tr></thead><tbody>");
            for(var fila:pagina.filas()){h.append("<tr data-registro=\"").append(fila.id()).append("\">");for(var col:columnas)celda(h,col.titulo(),celda(fila,col.clave(),s));celda(h,"Detalle",enlace(s.ruta()+"/"+fila.id(),detalle(s),false));h.append("</tr>");}h.append("</tbody></table></div>");
        }
        return Html.pagina(s.titulo(),h.toString(),sesion,false);
    }
    /** Consulta finalizada del Usuario: postura y resultados propios, sin fotos ni acciones de gestión. */
    public static String evaluacion(Sesion s,Detalle d){var e=d.evaluacion();StringBuilder h=new StringBuilder(enlace("/evaluaciones","← Evaluaciones",false)).append("<section class=\"card stack\"><div class=\"row between\"><h2>Puesto ").append(escapar(e.valor("numero"))).append("</h2>").append(riesgo(e)).append("</div><p>").append(ubicacion(e)).append("</p><h3>").append(escapar(e.valor("postura"))).append("</h3><p>").append(escapar(e.valor("criterio").equals("MAS_INADECUADA")?"Postura más inadecuada":"Mayor tiempo de exposición")).append(" · ").append(escapar(e.valor("minutos"))).append(" minutos por jornada</p><p class=\"texto-notas\">").append(escapar(e.valor("motivo"))).append("</p><p>").append(fecha(e.valor("fecha"))).append("</p>").append(enlace("/visitas/"+e.valor("visita"),"Ver visita",false)).append("</section><section class=\"stack\"><h2>Análisis guardados</h2>");
        int numero=0;for(var a:d.analisis())h.append("<div class=\"card row between\"><div>Análisis ").append(++numero).append(" · ").append(escapar(Formularios.etiqueta(a.lado()))).append("<div class=\"hint\">").append(Html.fechaHora(a.fecha())).append(" · ").append(escapar(a.responsable())).append("</div></div>").append(Html.riesgo(a.puntaje(),a.color(),a.nivel())).append("</div>");
        if(d.analisis().isEmpty())h.append("<p class=\"muted\">Esta evaluación no tiene análisis guardados.</p>");
        else h.append(enlace("/sugerencias?evaluacion="+e.id(),"Sugerencias de la evaluación",false));h.append(enlace("/pendientes?estado=TODOS&evaluacion="+e.id(),"Pendientes de la evaluación",false));return Html.pagina("Evaluación · Puesto "+e.valor("numero"),h.append("</section>").toString(),s);
    }
    private static String filtros(Pagina p,boolean contexto){var s=p.seccion();var f=p.filtros();StringBuilder h=new StringBuilder("<form class=\"card stack consultas-filtros\" method=\"get\" action=\"").append(s.ruta()).append("\"><div class=\"grid3\">");h.append(Formularios.campo(f,"q","Buscar","search",120,false));
        if(!contexto)h.append(filtro(p,"empresa"));h.append(filtro(p,"estado")).append("</div>");
        var extras=s.filtros().stream().filter(k->!Set.of("empresa","estado").contains(k)).filter(k->!contexto||Set.of("desde","hasta").contains(k)).toList();
        if(!extras.isEmpty()){h.append("<details class=\"guia filtros-extra\"").append(extras.stream().anyMatch(k->!f.getOrDefault(k,"").isEmpty())?" open":"").append("><summary>Más filtros</summary><div class=\"grid3\">");for(String key:extras)h.append(filtro(p,key));h.append("</div></details>");}
        if(f.containsKey("evaluacion"))h.append("<input type=\"hidden\" name=\"evaluacion\" value=\"").append(escapar(f.get("evaluacion"))).append("\">");
        if(f.containsKey("visita"))h.append("<input type=\"hidden\" name=\"visita\" value=\"").append(escapar(f.get("visita"))).append("\">");
        List<Formularios.Opcion> ordenes=new ArrayList<>(s.columnas().stream().filter(x->!contexto||!x.clave().equals("numero")).map(x->new Formularios.Opcion(x.clave(),x.titulo())).toList());if(s==SeccionConsulta.PENDIENTES)ordenes.addAll(List.of(new Formularios.Opcion("prioridad","Prioridad"),new Formularios.Opcion("fecha","Fecha de registro"),new Formularios.Opcion("fecha_limite","Fecha límite")));
        h.append("<div class=\"row consultas-orden\">").append(Formularios.selector(f,"orden","Ordenar por",ordenes,true)).append(Formularios.selector(f,"direccion","Dirección",List.of(new Formularios.Opcion("asc","Ascendente"),new Formularios.Opcion("desc","Descendente")),true)).append("<button class=\"btn p\">Aplicar filtros</button>");String limpiar=f.containsKey("evaluacion")?s.ruta()+"?evaluacion="+f.get("evaluacion"):s.ruta();return h.append(enlace(limpiar,"Limpiar filtros",false)).append("</div></form>").toString();
    }
    private static String filtro(Pagina p,String key){var f=p.filtros();String titulo=switch(key){case "empresa"->"Empresa";case "sede"->"Sede";case "salon"->"Salón";case "area"->"Área";case "cargo"->"Cargo";case "numero"->"Número de puesto";case "puntaje"->"Puntaje";case "color"->"Semáforo";case "nivel"->"Nivel oficial RULA";case "desde"->p.seccion()==SeccionConsulta.SUGERENCIAS?"Fecha límite desde":"Fecha desde";case "hasta"->p.seccion()==SeccionConsulta.SUGERENCIAS?"Fecha límite hasta":"Fecha hasta";default->"Estado";};
        if(key.equals("numero"))return Formularios.campo(f,key,titulo,"number",5,false).replace("type=\"number\"","type=\"number\" min=\"1\" max=\"32767\"");if(key.equals("desde")||key.equals("hasta"))return Formularios.campo(f,key,titulo,"date",10,false);
        List<Formularios.Opcion> opciones=new ArrayList<>();opciones.add(new Formularios.Opcion(key.equals("estado")?"TODOS":"","Todos"));
        if(p.catalogos().containsKey(key))for(var o:p.catalogos().get(key)){if(!key.equals("empresa")&&!f.getOrDefault("empresa","").isEmpty()&&o.empresa()!=Integer.parseInt(f.get("empresa")))continue;if(key.equals("salon")&&!f.getOrDefault("sede","").isEmpty()&&o.sede()!=Integer.parseInt(f.get("sede")))continue;opciones.add(new Formularios.Opcion(""+o.id(),o.nombre()));}
        else if(key.equals("estado"))for(var e:p.seccion().estados())opciones.add(new Formularios.Opcion(e,Formularios.etiqueta(e)));
        else if(key.equals("puntaje"))for(int n=1;n<=7;n++)opciones.add(new Formularios.Opcion(""+n,""+n));
        else for(String v:p.riesgos().getOrDefault(key,List.of()))opciones.add(new Formularios.Opcion(v,key.equals("nivel")?"Nivel "+v:Formularios.etiqueta(v)));
        return Formularios.selector(f,key,titulo,opciones,false);
    }
    private static String accion(SeccionConsulta s,Map<String,String> f,Contexto c){return switch(s){case EMPRESAS->enlace("/empresas/nueva","Nueva empresa",true);case RESERVAS->enlace("/reservas/nueva","Nueva reserva",true);case SUGERENCIAS->c==null?"":enlace("/sugerencias/nueva?evaluacion="+c.evaluacion(),"Escribir sugerencia",true);default->"";};}
    private static String celda(Fila r,String key,SeccionConsulta s){String valor=r.valor(key);return switch(key){case "puntaje"->riesgo(r);case "ubicacion"->ubicacion(r);case "asignacion"->escapar(r.valor("area_nombre").isEmpty()?"Sin área":r.valor("area_nombre"))+"<div class=\"muted small\">"+escapar(r.valor("cargo_nombre").isEmpty()?"Sin cargo":r.valor("cargo_nombre"))+"</div>";case "numero"->"<b>Puesto "+escapar(valor)+"</b>"+((s==SeccionConsulta.PENDIENTES||s==SeccionConsulta.SUGERENCIAS)?"<div class=\"muted small\">"+ubicacion(r)+"</div>":"");case "fecha"->fecha(valor)+(s==SeccionConsulta.RESERVAS?"<div class=\"small num\">"+escapar(r.valor("inicio").substring(0,5))+"–"+escapar(r.valor("fin").substring(0,5))+"</div>":"");case "estado"->"<span class=\"tag\">"+escapar(Formularios.etiqueta(valor))+"</span>";case "origen"->valor.equals("SISTEMA")?"Sugerencia del sistema":"Escrita por el Administrador";case "prioridad"->escapar(Formularios.etiqueta(valor));case "tipo"->escapar(s==SeccionConsulta.RESERVAS?PaginasReservas.categoria(valor):Formularios.etiqueta(valor));case "seguimiento"->escapar(r.valor("prioridad").isEmpty()?"Sin prioridad":Formularios.etiqueta(r.valor("prioridad")))+"<div class=\"small\">Límite: "+fecha(r.valor("fecha_limite"))+"</div><div class=\"muted small\">Registro: "+fecha(r.valor("fecha"))+"</div>";case "nombre"->escapar(valor)+(s==SeccionConsulta.SUGERENCIAS?"<div class=\"muted small\">"+escapar(Formularios.etiqueta(r.valor("tipo")))+"</div>":"");default->escapar(valor.isEmpty()?"Sin definir":valor);};}
    private static String ubicacion(Fila r){return String.join(" · ",List.of(r.valor("empresa_nombre"),r.valor("sede_nombre"),r.valor("salon_nombre")).stream().filter(x->!x.isEmpty()).map(Html::escapar).toList());}
    private static String riesgo(Fila r){return Html.riesgo(r.valor("puntaje").isEmpty()?null:Integer.valueOf(r.valor("puntaje")),r.valor("color"),r.valor("nivel").isEmpty()?0:Integer.parseInt(r.valor("nivel")));}
    private static String fecha(String s){if(s.isEmpty())return "Sin definir";return s.length()>10?Html.fechaHora(LocalDateTime.parse(s.replace(' ','T'))):Html.fecha(LocalDate.parse(s));}
    private static String detalle(SeccionConsulta s){return switch(s){case EMPRESAS->"Ver empresa";case SEDES->"Ver sede";case SALONES->"Ver salón";case PUESTOS->"Ver puesto";case RESERVAS->"Ver reserva";case VISITAS->"Ver visita";case EVALUACIONES->"Ver evaluación";case PENDIENTES->"Ver pendiente";case SUGERENCIAS->"Ver sugerencia";default->"Ver registro";};}
    private static void celda(StringBuilder h,String label,String html){h.append("<td data-label=\"").append(escapar(label)).append("\"><div class=\"cell-value\">").append(html).append("</div></td>");}
    private static String url(String ruta,Map<String,String> p){String q=p.entrySet().stream().filter(e->!e.getValue().isEmpty()).map(e->URLEncoder.encode(e.getKey(),StandardCharsets.UTF_8)+"="+URLEncoder.encode(e.getValue(),StandardCharsets.UTF_8)).collect(java.util.stream.Collectors.joining("&"));return ruta+(q.isEmpty()?"":"?"+q);}
}
